// XML to JSON Converter
// Parses XML input and converts it to a JSON object

var xmlInput = input.get("xmlInput");
var attributePrefix = (input.get("attributePrefix") || "@").trim();
var textProperty = (input.get("textProperty") || "#text").trim();
var trimText = input.get("trimText") !== "false";

if (!xmlInput || xmlInput.trim() === "") {
    log.error("XML input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "XML input is required");
    output.set("Json", "");
    output.set("JsonObject", null);
    tags.trigger("error");
} else {
    try {
        // Simple XML parser for Jint environment
        var xml = xmlInput.trim();

        // Remove XML declaration if present
        xml = xml.replace(/^<\?xml[^?]*\?>\s*/i, "");

        // State tracking
        var pos = 0;

        function skipWhitespace() {
            while (pos < xml.length && /\s/.test(xml[pos])) pos++;
        }

        function parseAttributeValue() {
            var quote = xml[pos];
            if (quote !== '"' && quote !== "'") return null;
            pos++;
            var start = pos;
            while (pos < xml.length && xml[pos] !== quote) pos++;
            var value = xml.substring(start, pos);
            pos++; // skip closing quote
            return decodeXmlEntities(value);
        }

        function decodeXmlEntities(str) {
            return str
                .replace(/&amp;/g, "&")
                .replace(/&lt;/g, "<")
                .replace(/&gt;/g, ">")
                .replace(/&quot;/g, '"')
                .replace(/&apos;/g, "'");
        }

        function parseName() {
            var start = pos;
            while (pos < xml.length && /[a-zA-Z0-9_:-]/.test(xml[pos])) pos++;
            return xml.substring(start, pos);
        }

        function parseElement() {
            skipWhitespace();
            if (pos >= xml.length || xml[pos] !== '<') return null;

            // Check for comment
            if (xml.substring(pos, pos + 4) === "<!--") {
                var endComment = xml.indexOf("-->", pos + 4);
                if (endComment === -1) pos = xml.length;
                else pos = endComment + 3;
                return parseElement();
            }

            // Check for CDATA
            if (xml.substring(pos, pos + 9) === "<![CDATA[") {
                var endCdata = xml.indexOf("]]>", pos + 9);
                var cdataContent = "";
                if (endCdata === -1) {
                    cdataContent = xml.substring(pos + 9);
                    pos = xml.length;
                } else {
                    cdataContent = xml.substring(pos + 9, endCdata);
                    pos = endCdata + 3;
                }
                return { type: "text", value: cdataContent };
            }

            // Skip processing instructions
            if (xml.substring(pos, pos + 2) === "<?") {
                var endPi = xml.indexOf("?>", pos + 2);
                if (endPi === -1) pos = xml.length;
                else pos = endPi + 2;
                return parseElement();
            }

            // Check for closing tag (shouldn't happen at top level)
            if (xml[pos + 1] === "/") return null;

            pos++; // skip '<'
            var tagName = parseName();
            if (!tagName) return null;

            var attrs = {};
            var hasAttrs = false;

            // Parse attributes
            while (pos < xml.length) {
                skipWhitespace();
                if (xml[pos] === "/" || xml[pos] === ">") break;

                var attrName = parseName();
                if (!attrName) break;

                skipWhitespace();
                if (xml[pos] === "=") {
                    pos++;
                    skipWhitespace();
                    var attrValue = parseAttributeValue();
                    attrs[attributePrefix + attrName] = attrValue;
                    hasAttrs = true;
                }
            }

            // Self-closing tag
            if (xml[pos] === "/") {
                pos += 2; // skip '/>' 
                return { type: "element", name: tagName, attrs: attrs, children: [] };
            }

            pos++; // skip '>'

            // Parse children
            var children = [];
            var textContent = "";

            while (pos < xml.length) {
                skipWhitespace();

                // Check for closing tag
                if (xml.substring(pos, pos + 2) === "</") {
                    pos += 2;
                    var closeName = parseName();
                    while (pos < xml.length && xml[pos] !== ">") pos++;
                    pos++; // skip '>'
                    break;
                }

                // Check for child element
                if (xml[pos] === "<") {
                    var child = parseElement();
                    if (child) {
                        if (child.type === "text") {
                            textContent += child.value;
                        } else {
                            children.push(child);
                        }
                    }
                } else {
                    // Text content
                    var start = pos;
                    while (pos < xml.length && xml[pos] !== "<") pos++;
                    var text = xml.substring(start, pos);
                    if (trimText) text = text.trim();
                    if (text) textContent += decodeXmlEntities(text);
                }
            }

            return {
                type: "element",
                name: tagName,
                attrs: attrs,
                children: children,
                text: textContent
            };
        }

        function elementToJson(el) {
            var result = {};
            var hasContent = false;

            // Add attributes
            var attrKeys = Object.keys(el.attrs);
            for (var i = 0; i < attrKeys.length; i++) {
                result[attrKeys[i]] = el.attrs[attrKeys[i]];
                hasContent = true;
            }

            // Group children by name
            var childGroups = {};
            for (var j = 0; j < el.children.length; j++) {
                var child = el.children[j];
                if (!childGroups[child.name]) {
                    childGroups[child.name] = [];
                }
                childGroups[child.name].push(child);
            }

            // Add children to result
            var groupKeys = Object.keys(childGroups);
            for (var k = 0; k < groupKeys.length; k++) {
                var name = groupKeys[k];
                var group = childGroups[name];
                if (group.length === 1) {
                    result[name] = elementToJson(group[0]);
                } else {
                    var arr = [];
                    for (var m = 0; m < group.length; m++) {
                        arr.push(elementToJson(group[m]));
                    }
                    result[name] = arr;
                }
                hasContent = true;
            }

            // Add text content
            if (el.text) {
                if (hasContent) {
                    result[textProperty] = el.text;
                } else {
                    return el.text; // Simple text-only element
                }
            }

            // Empty element
            if (!hasContent && !el.text) {
                return null;
            }

            return result;
        }

        // Parse the XML
        var rootElement = parseElement();

        if (!rootElement) {
            throw new Error("Failed to parse XML: no valid root element found");
        }

        // Convert to JSON object
        var jsonObj = {};
        jsonObj[rootElement.name] = elementToJson(rootElement);

        var jsonStr = json.stringify(jsonObj);

        output.set("Json", jsonStr);
        output.set("JsonObject", jsonObj);
        output.set("RootElement", rootElement.name);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        log.info("Successfully converted XML to JSON (" + jsonStr.length + " chars)");
        tags.trigger("success");

    } catch (ex) {
        log.error("Failed to convert XML: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "XML parse error: " + ex.message);
        output.set("Json", "");
        output.set("JsonObject", null);
        tags.trigger("error");
    }
}
